65: /**
66:  * Resolve an `agent_type` against the role registry into spawn overrides.
67:  *
68:  * - Omitted type + non-empty registry → fall back to a configured role
69:  *   ("general-purpose" if present, else the first available) instead of
70:  *   running a nameless ephemeral agent. Relaxed from the earlier "throw when
71:  *   agent_type omitted": the model habitually omits it, and a hard error just
72:  *   turned every spawn into a failure. Falling back to a real role keeps the
73:  *   tool-allowlist / system-prompt benefits without breaking the call.
74:  * - Omitted type + empty registry → empty overrides (true ephemeral; nothing
75:  *   to fall back to).
76:  * - Unknown explicit type → throw, so the LLM gets a clear correction rather
77:  *   than silently running a generic agent.
78:  */
79: export function resolveAgentTypeOverrides(
80:   agentType: string | undefined,
81:   registry: AgentDefinitionRegistry | undefined,
82: ): AgentTypeOverrides {
83:   const available = registry?.list().map((d) => d.name) ?? [];
84:   let resolvedType = agentType;
85:   if (!resolvedType) {
86:     if (available.length === 0) return {};
87:     resolvedType = available.includes(DEFAULT_AGENT_TYPE) ? DEFAULT_AGENT_TYPE : available[0]!;
88:   }
89:   const def = registry?.get(resolvedType);
90:   if (!def) {
91:     const list = available.join(", ") || "(none defined)";
92:     throw new Error(`unknown agent_type '${resolvedType}'. Available: ${list}`);
93:   }
94:   return {
95:     resolvedType,
96:     model: def.model,
97:     maxTurns: def.maxTurns,
98:     toolAllowlist: def.tools,
99:     skillAllowlist: namespacePluginSkills(def.skills, def.source, def.pluginName),
100:     sandboxMode: def.sandbox,
101:     mcpAllowlist: def.mcp,
102:     appendSystemPrompt: def.systemPrompt,
103:   };
104: }
