61: export function openRunSession(args: OpenRunSessionArgs): OpenRunSessionResult {
62:   const { options } = args;
63:   const continuation =
64:     options?.subAgentContinuation === undefined
65:       ? undefined
66:       : parseSubAgentContinuation(options.subAgentContinuation, getCurrentSid());
67:   if (options?.subAgentContinuation !== undefined && (!args.isSubAgent || !continuation)) {
68:     throw new SessionError("Invalid sub-agent continuation metadata or parent ownership");
69:   }

98:   if (options?.sessionId && args.sessionManager.exists(options.sessionId)) {
99:     resumedFromDisk = true;
100:     session = args.sessionManager.resumeForRun(options.sessionId);
101:     if (continuation) {
102:       const persisted = parseSubAgentContinuation(
103:         session.state.subAgentContinuation,
104:         session.state.parentSessionId,
105:       );
106:       if (
107:         session.state.parentSessionId !== continuation.parentSessionId ||
108:         (session.state.subAgentContinuation !== undefined &&
109:           (!persisted || !isDeepStrictEqual(persisted, continuation)))
110:       ) {
111:         throw new SessionError("Sub-agent continuation cannot change its parent or frozen scope");
112:       }
